import type { GameLocale } from '../types/i18n'
import { translateGameWikiText } from '../data/help/wikiI18n'

export const GAME_DEFAULT_LOCALE: GameLocale = 'fr'

export const GAME_LOCALE_OPTIONS: Array<{ id: GameLocale; label: string; tag: string }> = [
  { id: 'fr', label: 'Français', tag: 'fr-FR' },
  { id: 'en', label: 'English', tag: 'en-GB' },
  { id: 'de', label: 'Deutsch', tag: 'de-DE' },
  { id: 'nl', label: 'Nederlands', tag: 'nl-NL' },
  { id: 'es', label: 'Español', tag: 'es-ES' },
  { id: 'it', label: 'Italiano', tag: 'it-IT' },
  { id: 'pt', label: 'Português', tag: 'pt-PT' },
  { id: 'pl', label: 'Polski', tag: 'pl-PL' },
]

export function isGameLocale(value: unknown): value is GameLocale {
  return GAME_LOCALE_OPTIONS.some(option => option.id === value)
}

export function gameLocaleTag(locale: GameLocale) {
  return GAME_LOCALE_OPTIONS.find(option => option.id === locale)?.tag ?? 'fr-FR'
}

export function currentGameLocale(): GameLocale {
  if (typeof document !== 'undefined') {
    const documentLocale = document.documentElement.dataset.cluGameLocale
    if (isGameLocale(documentLocale)) return documentLocale
  }
  if (typeof localStorage !== 'undefined') {
    try {
      const raw = localStorage.getItem('clu-metropole-user-settings-v1')
      const locale = raw ? (JSON.parse(raw) as { locale?: unknown }).locale : null
      if (isGameLocale(locale)) return locale
    }
    catch { /* Préférence absente ou invalide : français. */ }
  }
  return GAME_DEFAULT_LOCALE
}

export function currentGameLocaleTag() {
  return gameLocaleTag(currentGameLocale())
}


const NUMBER_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const DATE_FORMATTER_CACHE = new Map<string, Intl.DateTimeFormat>()
const COLLATOR_CACHE = new Map<string, Intl.Collator>()
const INTEGER_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const COMPACT_NUMBER_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const COMPACT_CURRENCY_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const PERCENT_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const SIGNED_PERCENT_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const DECIMAL_1_FORMATTER_CACHE = new Map<string, Intl.NumberFormat>()
const NUMERIC_COLLATOR_CACHE = new Map<string, Intl.Collator>()

function intlOptionsKey(options: object | undefined) {
  if (!options) return ''
  return Object.entries(options)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, value]) => `${key}:${String(value)}`)
    .join('|')
}

export function gameNumberFormatter(
  options?: Intl.NumberFormatOptions,
  localeTag = currentGameLocaleTag(),
) {
  const key = `${localeTag}|${intlOptionsKey(options)}`
  let formatter = NUMBER_FORMATTER_CACHE.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(localeTag, options)
    NUMBER_FORMATTER_CACHE.set(key, formatter)
  }
  return formatter
}

export function formatGameNumber(
  value: number,
  options?: Intl.NumberFormatOptions,
  localeTag = currentGameLocaleTag(),
) {
  return gameNumberFormatter(options, localeTag).format(value)
}


function cachedNumberFormatter(
  cache: Map<string, Intl.NumberFormat>,
  localeTag: string,
  options: Intl.NumberFormatOptions,
) {
  let formatter = cache.get(localeTag)
  if (!formatter) {
    formatter = new Intl.NumberFormat(localeTag, options)
    cache.set(localeTag, formatter)
  }
  return formatter
}

export function formatGameInteger(value: number, localeTag = currentGameLocaleTag()) {
  return cachedNumberFormatter(INTEGER_FORMATTER_CACHE, localeTag, { maximumFractionDigits: 0 }).format(value)
}

export function formatGameNumberCompact(value: number, localeTag = currentGameLocaleTag()) {
  return cachedNumberFormatter(COMPACT_NUMBER_FORMATTER_CACHE, localeTag, {
    notation: 'compact',
    maximumFractionDigits: 1,
  }).format(value)
}

export function formatGameCurrencyCompact(value: number, localeTag = currentGameLocaleTag()) {
  return cachedNumberFormatter(COMPACT_CURRENCY_FORMATTER_CACHE, localeTag, {
    style: 'currency',
    currency: 'EUR',
    notation: 'compact',
    maximumFractionDigits: 1,
  }).format(value)
}

export function formatGamePercent(value: number, localeTag = currentGameLocaleTag()) {
  return cachedNumberFormatter(PERCENT_FORMATTER_CACHE, localeTag, {
    style: 'percent',
    maximumFractionDigits: 0,
  }).format(value)
}

export function formatGameSignedPercent(value: number, localeTag = currentGameLocaleTag()) {
  return cachedNumberFormatter(SIGNED_PERCENT_FORMATTER_CACHE, localeTag, {
    style: 'percent',
    maximumFractionDigits: 0,
    signDisplay: 'always',
  }).format(value)
}

export function formatGameDecimal1(value: number, localeTag = currentGameLocaleTag()) {
  return cachedNumberFormatter(DECIMAL_1_FORMATTER_CACHE, localeTag, { maximumFractionDigits: 1 }).format(value)
}

export function gameDateFormatter(
  options?: Intl.DateTimeFormatOptions,
  localeTag = currentGameLocaleTag(),
) {
  const key = `${localeTag}|${intlOptionsKey(options)}`
  let formatter = DATE_FORMATTER_CACHE.get(key)
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(localeTag, options)
    DATE_FORMATTER_CACHE.set(key, formatter)
  }
  return formatter
}

export function gameCollator(
  options?: Intl.CollatorOptions,
  localeTag = currentGameLocaleTag(),
) {
  const key = `${localeTag}|${intlOptionsKey(options)}`
  let collator = COLLATOR_CACHE.get(key)
  if (!collator) {
    collator = new Intl.Collator(localeTag, options)
    COLLATOR_CACHE.set(key, collator)
  }
  return collator
}

export function gameNumericCollator(localeTag = currentGameLocaleTag()) {
  let collator = NUMERIC_COLLATOR_CACHE.get(localeTag)
  if (!collator) {
    collator = new Intl.Collator(localeTag, { numeric: true, sensitivity: 'base' })
    NUMERIC_COLLATOR_CACHE.set(localeTag, collator)
  }
  return collator
}

