function translateInlineKnownLabel(value: string, locale: Exclude<GameLocale, 'fr'>): string {
  return FINAL_EXACT_5[value]?.[locale]
    ?? FINAL_EXACT_3[value]?.[locale]
    ?? FINAL_EXACT_2[value]?.[locale]
    ?? FINAL_EXACT[value]?.[locale]
    ?? EXACT[value]?.[locale]
    ?? value
}

function translateMunicipalityRequestCopy(value: string, locale: Exclude<GameLocale, 'fr'>): string {
  const direct = translateInlineKnownLabel(value, locale)
  if (direct !== value) return direct
  const boost = value.match(/^un renforcement de (.+)$/i)
  if (!boost) return value
  const target = boost[1]
  return ({
    en: `a service boost for ${target}`,
    de: `eine Verstärkung für ${target}`,
    nl: `een versterking van ${target}`,
    es: `un refuerzo de ${target}`,
    it: `un potenziamento di ${target}`,
    pt: `um reforço de ${target}`,
    pl: `wzmocnienie dla ${target}`,
  })[locale]
}


