function translateLexically(text: string, locale: Exclude<GameLocale, 'fr'>) {
  const lexicon = LEXICON[locale]
  let changed = false
  const translated = text.replace(/[A-Za-zÀ-ÖØ-öø-ÿŒœ’'-]+/g, token => {
    if (!Object.prototype.hasOwnProperty.call(lexicon, token)) return token
    const replacement = lexicon[token]
    if (replacement !== undefined) { changed = true; return replacement }
    return token
  })
  return changed ? translated.replace(/\s{2,}/g, ' ') : text
}


