export function translateGameText(input: string, locale: GameLocale): string {
  if (locale === 'fr' || !input) return input
  const target = locale as Exclude<GameLocale, 'fr'>
  const leading = input.match(/^\s*/)?.[0] ?? ''
  const trailing = input.match(/\s*$/)?.[0] ?? ''
  const text = input.trim()
  if (!text) return input
  const wikiExact = translateGameWikiText(text, locale)
  if (wikiExact) return `${leading}${wikiExact}${trailing}`
  const exact = FINAL_EXACT_6[text]?.[target] ?? FINAL_EXACT_5[text]?.[target] ?? FINAL_EXACT_4[text]?.[target] ?? FINAL_EXACT_3[text]?.[target] ?? FINAL_EXACT_2[text]?.[target] ?? FINAL_EXACT[text]?.[target] ?? EXACT[text]?.[target]
  if (exact) return `${leading}${exact}${trailing}`
  for (const item of [...FINAL_DYNAMIC_PATTERNS_2, ...FINAL_DYNAMIC_PATTERNS, ...DYNAMIC_PATTERNS]) {
    const match = text.match(item.pattern)
    if (match) {
      const prefix = item.build(match, target)
      const tail = text.slice(match[0].length)
      return `${leading}${prefix}${translateLexically(tail, target)}${trailing}`
    }
  }
  return `${leading}${translateLexically(text, target)}${trailing}`
}
